  console.log('Seeding database...');

  // Categories
  const categories = await Promise.all([
    db.category.upsert({ where: { slug: 'qualite' }, update: {}, create: { name: 'Qualité', slug: 'qualite', description: 'Normes ISO, management de la qualité, amélioration continue', color: '#059669', order: 0 } }),
    db.category.upsert({ where: { slug: 'hygiene' }, update: {}, create: { name: 'Hygiène', slug: 'hygiene', description: 'HACCP, sécurité alimentaire, bonnes pratiques d\'hygiène', color: '#0891b2', order: 1 } }),
    db.category.upsert({ where: { slug: 'securite' }, update: {}, create: { name: 'Sécurité', slug: 'securite', description: 'Sécurité au travail, EPI, analyse des risques, prévention', color: '#dc2626', order: 2 } }),
    db.category.upsert({ where: { slug: 'environnement' }, update: {}, create: { name: 'Environnement', slug: 'environnement', description: 'Développement durable, gestion des déchets, ISO 14001', color: '#16a34a', order: 3 } }),
    db.category.upsert({ where: { slug: 'management' }, update: {}, create: { name: 'Management QHSE', slug: 'management', description: 'Systèmes de management intégré, audit, SMQ', color: '#7c3aed', order: 4 } }),
    db.category.upsert({ where: { slug: 'reglementation' }, update: {}, create: { name: 'Réglementation', slug: 'reglementation', description: 'Droit du travail, normes légales, conformité réglementaire', color: '#d97706', order: 5 } }),
  ]);

  // Articles
  const articlesData = [
    { title: 'Comprendre la norme ISO 9001 : Guide complet pour les entreprises', slug: 'comprendre-norme-iso-9001', excerpt: 'La norme ISO 9001 est la référence internationale en matière de management de la qualité. Découvrez ses exigences, ses avantages et comment l\'implémenter dans votre entreprise.', content: `La norme ISO 9001 est le standard international le plus reconnu en matière de systèmes de management de la qualité (SMQ). Elle fournit un cadre structuré pour aider les organisations à améliorer leurs performances, satisfaire leurs clients et démontrer leur conformité aux exigences réglementaires.\n\n## Les principes fondamentaux de l'ISO 9001\n\nL'ISO 9001 repose sur sept principes de management de la qualité qui guident l'ensemble de la démarche :\n\n1. **Orientation client** : Toutes les activités de l'organisation doivent être orientées vers la satisfaction des besoins et attentes des clients. Cela implique de bien comprendre leurs exigences, de mesurer leur satisfaction et d'agir sur les retours.\n\n2. **Leadership** : La direction doit établir une vision claire, définir des objectifs qualité et créer un environnement favorisant l'engagement de chaque collaborateur. Le leadership est le moteur du système de management.\n\n3. **Implication du personnel** : Les employés à tous les niveaux sont essentiels. Leur compétence, leur implication et leur empowerment permettent d'atteindre les objectifs qualité de manière durable.\n\n4. **Approche processus** : L'organisation doit être gérée comme un ensemble de processus interconnectés. Chaque processus a des entrées, des activités et des sorties qui contribuent à la création de valeur.\n\n5. **Amélioration** : L'amélioration continue est au cœur de la norme. Elle implique l'utilisation du cycle PDCA (Plan-Do-Check-Act) pour identifier et mettre en œuvre des améliorations permanentes.\n\n6. **Prise de décision fondée sur des preuves** : Les décisions doivent être basées sur l'analyse de données et d'informations factuelles, et non sur des suppositions ou des intuitions.\n\n7. **Gestion des relations** : La gestion efficace des relations avec les parties intéressées (fournisseurs, partenaires, société) contribue à la réussite durable de l'organisation.\n\n## Les étapes de mise en œuvre\n\nLa mise en place de l'ISO 9001 suit généralement un processus structuré en plusieurs phases :\n\n- **Phase 1 : Diagnostic initial** - Évaluation de l'existant et identification des écarts par rapport aux exigences de la norme.\n- **Phase 2 : Planification** - Définition de la politique qualité, des objectifs et de la cartographie des processus.\n- **Phase 3 : Mise en place** - Déploiement des processus, rédaction des procédures et formation du personnel.\n- **Phase 4 : Audit interne** - Vérification de la conformité du système mis en place.\n- **Phase 5 : Certification** - Audit par un organisme tiers accrédité.\n\n## Bénéfices pour l'entreprise\n\nLes entreprises certifiées ISO 9001 constatent généralement une amélioration significative de leur performance opérationnelle, une réduction des non-conformités, une meilleure fidélisation de la clientèle et un accès facilité aux marchés publics et internationaux.`, categoryId: categories[0].id, coverImage: '/images/iso9001.jpg', featured: true },
    { title: 'Les EPI : Équipements de Protection Individuelle essentiels', slug: 'epi-equipements-protection-individuelle', excerpt: 'Les Équipements de Protection Individuelle (EPI) constituent la dernière ligne de défense contre les risques professionnels. Apprenez à les choisir, les utiliser et les entretenir.', content: `Les Équipements de Protection Individuelle (EPI) sont des dispositifs ou des moyens portés par une personne en vue de la protéger contre un ou plusieurs risques susceptibles de menacer sa santé ou sa sécurité. Dans le domaine du travail, et particulièrement sur les chantiers et environnements industriels, la sécurité n'est jamais un détail.\n\n## Classification des EPI\n\nLes EPI sont classés en trois catégories selon le niveau de risque :\n\n### Catégorie I : Risques mineurs\nProtection contre les risques superficiels tels que les petites abrasions ou le nettoyage de surfaces. Exemples : gants de jardinage, lunettes de soleil.\n\n### Catégorie II : Risques intermédiaires\nProtection contre les risques de blessures moyennes à graves. Exemples : casques de protection, gants de manutention, protections auditives.\n\n### Catégorie III : Risques graves ou mortels\nProtection contre les dangers pouvant mettre en danger la vie. Exemples : harnais de sécurité, appareils de protection respiratoire, combinaisons chimiques.\n\n## Les principaux types d'EPI\n\n- **Protection de la tête** : Casques, casquettes et coiffes de protection contre les chutes d'objets, les contacts électriques et les projections.\n- **Protection des yeux et du visage** : Lunettes, écrans faciaux et visières contre les projections, les éclats, les poussières et les rayonnements.\n- **Protection auditive** : Bouchons d'oreilles, casques anti-bruit pour prévenir les traumatismes sonores.\n- **Protection respiratoire** : Masques, demi-masques et appareils filtrants contre les poussières, gaz et vapeurs toxiques.\n- **Protection des mains** : Gants de protection adaptés au risque (chimique, thermique, mécanique, électrique).\n- **Protection des pieds** : Chaussures de sécurité avec embout, semelle anti-perforation et antidérapante.\n- **Protection du corps** : Vêtements de protection, harnais de sécurité, combinaisons.\n\n## Obligations de l'employeur\n\nL'employeur a l'obligation légale de fournir gratuitement les EPI nécessaires à ses salariés, de s'assurer qu'ils sont adaptés au risque, de former les travailleurs à leur utilisation et de vérifier régulièrement leur bon état.`, categoryId: categories[2].id, coverImage: '/images/epi.jpg', featured: true },
    { title: 'La gestion des produits chimiques et dangereux au travail', slug: 'gestion-produits-chimiques-dangereux', excerpt: 'Inhalation de vapeurs toxiques, risques d\'incendies et d\'explosions, pollution des sols : la gestion des produits chimiques est un enjeu majeur de la sécurité au travail.', content: `La manipulation de produits chimiques et dangereux en milieu professionnel représente un risque majeur pour la santé et la sécurité des travailleurs. Une gestion rigoureuse de ces substances est indispensable pour prévenir les accidents, les maladies professionnelles et la pollution environnementale.\n\n## Identification des dangers\n\nLa première étape de la gestion des produits chimiques consiste à identifier correctement les dangers associés à chaque substance. Cela passe par :\n\n- **L'étiquetage** : Lecture et compréhension des étiquettes réglementaires comportant les pictogrammes de danger, les mentions d'avertissement et les phrases de risque.\n- **Les fiches de données de sécurité (FDS)** : Documents obligatoires fournis par le fabricant, contenant toutes les informations sur les dangers, les mesures de prévention et les premiers secours.\n- **La classification** : Utilisation du SGH (Système Général Harmonisé) pour classer les substances selon leurs propriétés physico-chimiques, toxicologiques et écotoxicologiques.\n\n## Risques principaux\n\nLes principaux risques liés aux produits chimiques incluent :\n- **Risques pour la santé** : Irritation, brûlures, allergies, troubles respiratoires, cancers, effets sur la reproduction.\n- **Risques physiques** : Incendies, explosions, réactions dangereuses.\n- **Risques environnementaux** : Contamination des sols, de l'eau et de l'air.\n\n## Mesures de prévention\n\nLa hiérarchie des mesures de prévention (élimination, substitution, mesures techniques, mesures organisationnelles, EPI) doit être systématiquement appliquée pour réduire les risques à un niveau acceptable.`, categoryId: categories[2].id, coverImage: '/images/chimiques.jpg', featured: false },
    { title: 'ISO 14001 : Le système de management environnemental', slug: 'iso-14001-management-environnemental', excerpt: 'L\'ISO 14001 est la norme internationale de référence pour les systèmes de management environnemental. Découvrez comment elle aide les organisations à réduire leur impact écologique.', content: `L'ISO 14001 est la norme internationale qui définit les exigences d'un système de management environnemental (SME). Elle permet aux organisations de mettre en place une approche systématique pour améliorer leur performance environnementale, réduire leur impact écologique et respecter la réglementation en vigueur.\n\n## Les exigences clés de l'ISO 14001\n\nLa norme repose sur le cycle d'amélioration continue PDCA (Plan-Do-Check-Act) et inclut des exigences portant sur :\n\n- **Le contexte de l'organisation** : Compréhension des enjeux internes et externes, des besoins des parties intéressées et de la portée du SME.\n- **La leadership** : Engagement de la direction en faveur du management environnemental.\n- **La planification** : Identification des aspects environnementaux, évaluation des risques et opportunités, définition des objectifs et planification des actions.\n- **Le soutien** : Ressources, compétences, sensibilisation, communication et documentation.\n- **L'opérationnalité** : Maîtrise opérationnelle, préparation aux situations d'urgence.\n- **L'évaluation des performances** : Surveillance, mesure, analyse, audit interne et revue de direction.\n\n## Bénéfices de la certification ISO 14001\n\nLa certification ISO 14001 apporte de nombreux avantages : réduction de la consommation d'énergie et de matières premières, diminution des déchets et des émissions, amélioration de l'image de marque, conformité réglementaire accrue et accès à de nouveaux marchés sensibles à l'environnement.`, categoryId: categories[3].id, coverImage: '/images/iso14001.jpg', featured: true },
    { title: 'Propreté et organisation du chantier : Facteurs clés de sécurité', slug: 'proprete-organisation-chantier', excerpt: 'Un chantier propre et bien organisé constitue un facteur déterminant pour la sécurité au travail. Découvrez les bonnes pratiques et les outils pour maintenir un environnement de travail sûr.', content: `Un chantier propre et bien organisé n'est pas seulement agréable à voir : il constitue un facteur déterminant pour la sécurité au travail. La méthode des 5S, issue du Lean Management, est un outil puissant pour instaurer et maintenir l'ordre sur les lieux de travail.\n\n## Les 5S : Méthode et application\n\n### Seiri (Débarras)\nSéparer ce qui est utile de ce qui ne l'est pas. Éliminer les outils, matériaux et équipements inutiles du chantier pour réduire les risques de trébuchement, de chute d'objets et d'incendie.\n\n### Seiton (Rangement)\nChaque chose à sa place et chaque chose en place. Définir des emplacements précis pour les outils, les matériaux et les équipements de protection. Utiliser des marquages au sol et des panneaux de signalisation.\n\n### Seiso (Nettoyage)\nNettoyer régulièrement le chantier pour éliminer les poussières, les débris et les substances dangereuses. Le nettoyage est aussi un moment d'inspection qui permet de détecter les anomalies.\n\n### Seiketsu (Standardisation)\nÉtablir des règles et procédures claires pour maintenir les trois premiers S dans le temps. Ces standards doivent être visibles, compréhensibles par tous et régulièrement mis à jour.\n\n### Shitsuke (Discipline)\nMaintenir les acquis par la discipline et l'habitude. Chaque travailleur doit s'engager à respecter les règles établies et à participer activement à l'amélioration continue de l'environnement de travail.\n\n## Bénéfices mesurables\n\nLes entreprises qui appliquent rigoureusement la méthode des 5S constatent une réduction significative des accidents du travail (jusqu'à 30%), une amélioration de la productivité, une réduction du temps de recherche d'outils et une meilleure image de l'entreprise.`, categoryId: categories[2].id, coverImage: '/images/proprete.jpg', featured: false },
    { title: 'HACCP : Les principes de la sécurité alimentaire', slug: 'haccp-securite-alimentaire', excerpt: 'Le système HACCP est la méthode de référence pour garantir la sécurité des aliments. Découvrez ses 7 principes fondamentaux et leur application pratique.', content: `Le système HACCP (Hazard Analysis Critical Control Points) - Analyse des Dangers et Maîtrise des Points Critiques - est une approche préventive de la sécurité alimentaire reconnue mondialement. Développé à l'origine pour le programme spatial américain, il est aujourd'hui le standard de référence dans l'industrie agroalimentaire.\n\n## Les 7 principes HACCP\n\n### Principe 1 : Analyse des dangers\nIdentifier tous les dangers potentiels (biologiques, chimiques, physiques) à chaque étape du processus de fabrication. Cette analyse doit être exhaustive et documentée.\n\n### Principe 2 : Détermination des CCP\nIdentifier les Points Critiques de Contrôle - les étapes où un contrôle peut être appliqué pour prévenir, éliminer ou réduire un danger à un niveau acceptable.\n\n### Principe 3 : Établissement des limites critiques\nDéfinir les valeurs limites qui séparent l'acceptabilité de l'inacceptabilité pour chaque CCP (température, temps, pH, humidité, etc.).\n\n### Principe 4 : Établissement des procédures de surveillance\nMettre en place un système de surveillance pour chaque CCP afin de s'assurer que les limites critiques sont respectées en continu.\n\n### Principe 5 : Actions correctives\nDéfinir les actions à entreprendre lorsque la surveillance indique qu'un CCP n'est pas maîtrisé.\n\n### Principe 6 : Vérification\nÉtablir des procédures de vérification pour confirmer que le système HACCP fonctionne efficacement.\n\n### Principe 7 : Documentation\nTenir des registres et de la documentation pour démontrer la conformité du système et sa maîtrise effective.`, categoryId: categories[1].id, coverImage: '/images/haccp.jpg', featured: true },
    { title: 'L\'audit QHSE : Un outil stratégique d\'amélioration continue', slug: 'audit-qhse-amelioration-continue', excerpt: 'L\'audit QHSE est un processus systématique d\'évaluation de la conformité et de l\'efficacité du système de management. Découvrez les différentes types d\'audits et leur méthodologie.', content: `L'audit QHSE est un outil essentiel pour toute organisation souhaitant évaluer, maintenir et améliorer son système de management Qualité, Hygiène, Sécurité et Environnement. Il permet de vérifier la conformité aux exigences réglementaires et normatives, d'identifier les opportunités d'amélioration et de mesurer l'efficacité des actions mises en place.\n\n## Types d'audits QHSE\n\n- **Audits internes** : Réalisés par l'organisation elle-même ou en son nom. Ils sont obligatoires dans le cadre de la certification ISO.\n- **Audits externes** : Réalisés par des organismes tiers indépendants dans le cadre de la certification ou du contrôle réglementaire.\n- **Audits de conformité** : Vérifient la conformité aux exigences spécifiées (normes, lois, réglementations).\n- **Audits de système** : Évaluent l'efficacité globale du système de management.\n- **Audits de processus** : Se concentrent sur un processus particulier pour évaluer son efficacité.\n\n## Méthodologie d'audit\n\nLa réalisation d'un audit suit généralement un processus en cinq étapes : la planification (définir l'objectif, le périmètre, les critères), la préparation (revue documentaire, élaboration du questionnaire), la réalisation (entretiens, observations, vérifications), l'analyse (traitement des constats, classification des non-conformités) et le rapport (rédaction et suivi des actions correctives).`, categoryId: categories[4].id, coverImage: '/images/audit.jpg', featured: false },
    { title: 'ISO 45001 : La nouvelle norme en santé et sécurité au travail', slug: 'iso-45001-sante-securite-travail', excerpt: 'L\'ISO 45001 remplace l\'OHSAS 18001 comme référence internationale en santé et sécurité au travail. Découvrez ses exigences et les avantages de sa mise en œuvre.', content: `L'ISO 45001 est la norme internationale qui définit les exigences d'un système de management de la santé et de la sécurité au travail (SST). Publiée en mars 2018, elle remplace l'OHSAS 18001 et apporte une approche plus moderne et intégrée de la prévention des risques professionnels.\n\n## Principales évolutions par rapport à l'OHSAS 18001\n\nL'ISO 45001 introduit plusieurs changements majeurs :\n- **Structure de haut niveau (HLS)** : Alignement avec l'ISO 9001 et l'ISO 14001 pour faciliter l'intégration des systèmes de management.\n- **Contexte de l'organisation** : Nécessité de comprendre les facteurs internes et externes influençant le système SST.\n- **Parties intéressées** : Identification et prise en compte des attentes des travailleurs et autres parties.\n- **Leadership et engagement** : Responsabilité renforcée de la direction.\n- **Risque et opportunité** : Approche proactive basée sur l'évaluation des risques et des opportunités.\n- **Élimination des dangers et réduction des risques** : Hiérarchie des mesures de contrôle renforcée.\n\n## Bénéfices de la certification\n\nLa mise en place de l'ISO 45001 permet de réduire les accidents du travail et les maladies professionnelles, d'améliorer le bien-être des travailleurs, de réduire les coûts liés aux absences et aux accidents, de renforcer la réputation de l'entreprise et de démontrer la conformité réglementaire.`, categoryId: categories[2].id, coverImage: '/images/iso45001.jpg', featured: true },
    { title: 'La gestion des déchets en entreprise : Réglementation et bonnes pratiques', slug: 'gestion-dechets-entreprise', excerpt: 'La gestion des déchets est un enjeu environnemental et réglementaire majeur pour les entreprises. Découvrez les obligations légales et les solutions pratiques pour une gestion responsable.', content: `La gestion des déchets en entreprise est soumise à une réglementation stricte qui vise à réduire l'impact environnemental des activités professionnelles. Le principe fondamental est celui de la hiérarchie des déchets : prévention, réutilisation, recyclage, valorisation, et enfin élimination.\n\n## La hiérarchie des déchets\n\n1. **Prévention** : Réduire à la source la quantité et la nocivité des déchets produits.\n2. **Réutilisation** : Préparer des déchets pour qu'ils servent à nouveau au même usage.\n3. **Recyclage** : Transformer les déchets en matières premières secondaires.\n4. **Valorisation énergétique** : Utiliser les déchets comme source d'énergie.\n5. **Élimination** : Dernier recours : stockage ou incinération sans valorisation.\n\n## Obligations réglementaires\n\nLes entreprises ont l'obligation de trier leurs déchets, de faire appel à des collecteurs agréés, de tenir un registre des déchets dangereux et de produire un bilan déchets annuel. Le non-respect de ces obligations peut entraîner des sanctions pénales et financières importantes.\n\n## Bonnes pratiques\n\nMettre en place des poubelles de tri sélectif clairement identifiées, former le personnel au tri, réduire les emballages à la source, favoriser le réemploi des matériaux et collaborer avec des filières de recyclage certifiées.`, categoryId: categories[3].id, coverImage: '/images/dechets.jpg', featured: false },
    { title: 'Les risques professionnels : Identification et prévention', slug: 'risques-professionnels-identification-prevention', excerpt: 'L\'identification et l\'évaluation des risques professionnels sont la base de toute démarche de prévention. Découvrez les principales familles de risques et les méthodes d\'évaluation.', content: `L'identification et l'évaluation des risques professionnels constituent la pierre angulaire de toute démarche de prévention en santé et sécurité au travail. En France, le Document Unique d'Évaluation des Risques (DUER) est l'outil obligatoire qui formalise cette démarche.\n\n## Les principales familles de risques\n\n### Risques physiques\nBruit, vibrations, rayonnements ionisants et non ionisants, températures extrêmes, électricité, chute de plain-pied et de hauteur.\n\n### Risques chimiques\nExposition aux substances dangereuses, poussières, fumées, gaz et vapeurs toxiques.\n\n### Risques biologiques\nExposition aux agents biologiques (bactéries, virus, champignons) dans les secteurs de la santé, de l'agriculture et du traitement des déchets.\n\n### Risques ergonomiques\nManutention manuelle, postures contraignantes, mouvements répétitifs, travail sur écran.\n\n### Risques psychosociaux (RPS)\nStress au travail, harcèlement, burn-out, charge mentale excessive.\n\n### Risques organisationnels\nTravail de nuit, horaires atypiques, sous-traitance en cascade.\n\n## Méthodes d'évaluation\n\nPlusieurs méthodes sont utilisées pour évaluer les risques : la méthode EVA (Emploi, Vulnérabilité, Arbitrage), la méthode Kinney, l'arbre des causes et l'analyse des modes de défaillance (AMDEC). Le choix de la méthode dépend du contexte et de la complexité des situations à analyser.`, categoryId: categories[2].id, coverImage: '/images/risques.jpg', featured: false },
    { title: 'La VAE : Valorisez votre expérience en diplôme QHSE', slug: 'vae-diplome-qhse', excerpt: 'La Validation des Acquis de l\'Expérience permet d\'obtenir un diplôme grâce à votre expérience professionnelle. L\'IICP vous accompagne dans cette démarche pour valoriser votre expertise QHSE.', content: `La Validation des Acquis de l'Expérience (VAE) est un droit inscrit dans le Code de l'éducation qui permet à toute personne, quel que soit son âge, son statut ou son niveau de formation, de faire valider les acquis de son expérience professionnelle pour obtenir un diplôme, un titre ou un certificat de qualification.\n\n## Comment fonctionne la VAE ?\n\nLa démarche VAE se déroule en plusieurs étapes clés :\n\n1. **Éligibilité** : Vérifier que l'expérience professionnelle (salariée, non salariée, bénévole) correspond à la durée requise (généralement 1 an minimum, soit 1607 heures).\n\n2. **Constitution du dossier** : Rédaction d'un dossier détaillé décrivant les expériences et les compétences acquises en lien avec le référentiel du diplôme visé.\n\n3. **Accompagnement** : Bénéficier de l'accompagnement d'un conseiller VAE pour structurer le dossier et préparer l'entretien.\n\n4. **Jury** : Présentation devant un jury qui évalue la correspondance entre les acquis et les exigences du diplôme.\n\n5. **Résultat** : Le jury peut accorder la validation totale, une validation partielle ou un refus.\n\n## Les diplômes QHSE accessibles par VAE\n\nL'IICP propose l'accès par VAE à sa Licence Professionnelle et à son Master Professionnel en QHSE, permettant aux professionnels expérimentés d'obtenir une reconnaissance formelle de leurs compétences.`, categoryId: categories[5].id, coverImage: '/images/vae.jpg', featured: false },
    { title: 'Le Lean Management appliqué au QHSE', slug: 'lean-management-qhse', excerpt: 'Le Lean Management et le QHSE partagent des objectifs communs : l\'amélioration continue et l\'élimination des gaspillages. Découvrez comment combiner ces deux approches.', content: `Le Lean Management et la démarche QHSE partagent des principes fondamentaux communs : l'amélioration continue, la recherche de l'excellence opérationnelle, l'implication des collaborateurs et la gestion orientée processus. Leur combinaison crée une synergie puissante pour les organisations.\n\n## Les outils Lean applicables au QHSE\n\n### Le 5S\nLa méthode des 5S (Seiri, Seiton, Seiso, Seiketsu, Shitsuke) est directement transposable au domaine QHSE. Un environnement de travail organisé et propre réduit significativement les risques d'accidents.\n\n### Le Kaizen\nLa philosophie Kaizen (amélioration continue) est au cœur de la démarche QHSE. Les petites améliorations quotidiennes cumulées conduisent à des progrès significatifs en matière de sécurité et de qualité.\n\n### La cartographie VSM\nLa Value Stream Mapping (cartographie de la chaîne de valeur) peut être adaptée pour identifier les gaspillages et les risques dans les processus QHSE.\n\n### Le PDCA\nLe cycle Plan-Do-Check-Act est commun au Lean et aux normes ISO. Il constitue le moteur de l'amélioration continue dans les deux approches.\n\n## Bénéfices de l'intégration Lean-QHSE\n\nL'intégration du Lean Management dans la démarche QHSE permet de réduire les coûts de non-qualité, d'améliorer la sécurité en éliminant les gaspillages à la source, d'augmenter l'efficacité des audits et de renforcer la culture d'amélioration continue au sein de l'organisation.`, categoryId: categories[4].id, coverImage: '/images/lean.jpg', featured: false },
    { title: 'La signalisation de sécurité au travail : Guide complet', slug: 'signalisation-securite-travail', excerpt: 'La signalisation de sécurité est un élément essentiel de la prévention des risques professionnels. Ce guide vous présente les différents types de panneaux et leurs règles d\'utilisation.', content: `La signalisation de sécurité au travail constitue un moyen de prévention complémentaire indispensable. Elle fournit des informations visuelles immédiates sur les risques présents, les consignes à respecter et les équipements de protection à utiliser.\n\n## Les catégories de signalisation\n\n### Signalisation d'interdiction (rond rouge)\nPanneaux interdisant un comportement susceptible de provoquer un danger. Exemples : défense de fumer, accès interdit aux personnes étrangères, interdiction d'éteindre avec de l'eau.\n\n### Signalisation d'avertissement (triangle jaune)\nPanneaux avertissant d'un risque ou d'un danger. Exemples : risque électrique, risque de chute, danger général, substances radioactives.\n\n### Signalisation d'obligation (rond bleu)\nPanneaux imposant un comportement ou une action spécifique. Exemples : obligation de porter un casque, des gants, des lunettes de protection.\n\n### Signalisation de secours (carré vert)\nPanneaux indiquant les issues de secours, les équipements de premiers secours et les moyens de lutte contre l'incendie. Exemples : sortie de secours, extincteur, trousses de premiers secours.\n\n## Règles d'implantation\n\nLa signalisation doit être visible de loin, placée à une hauteur adaptée, éclairée si nécessaire et régulièrement entretenue. Le nombre et l'emplacement des panneaux doivent être déterminés par une analyse des risques du lieu de travail.`, categoryId: categories[2].id, coverImage: '/images/signalisation.jpg', featured: false },
    { title: 'La RSE et le QHSE : Deux démarches complémentaires', slug: 'rse-qhse-demarches-complementaires', excerpt: 'La Responsabilité Sociétale des Entreprises (RSE) et le QHSE sont deux démarches de plus en plus intégrées. Découvrez comment elles se renforcent mutuellement.', content: `La Responsabilité Sociétale des Entreprises (RSE) et la démarche QHSE sont de plus en plus perçues comme complémentaires et interdépendantes. Si le QHSE se concentre sur la qualité, la sécurité et l'environnement au sein de l'entreprise, la RSE élargit cette vision à l'ensemble des parties prenantes et aux dimensions sociales, économiques et environnementales.\n\n## Points de convergence\n\nLes deux démarches partagent plusieurs objectifs communs :\n- La protection de la santé et de la sécurité des travailleurs\n- La réduction de l'impact environnemental\n- Le respect de la réglementation\n- L'amélioration continue des performances\n- L'engagement des parties prenantes\n\n## L'ISO 26000 comme cadre de référence\n\nLa norme ISO 26000 fournit des lignes directrices sur la responsabilité sociétale. Elle couvre sept questions centrales : la gouvernance, les droits de l'homme, les relations et conditions de travail, l'environnement, les bonnes pratiques des affaires, les questions de consommation et le développement des communautés.\n\n## Intégration pratique\n\nL'intégration de la RSE et du QHSE peut se faire en élargissant le périmètre du système de management QHSE pour inclure les enjeux sociaux et sociétaux, en alignant la politique QHSE avec les objectifs de développement durable et en mesurant les indicateurs de performance communs.`, categoryId: categories[4].id, coverImage: '/images/rse.jpg', featured: false },
    { title: 'Les accidents du travail : Analyse et prévention', slug: 'accidents-travail-analyse-prevention', excerpt: 'L\'analyse des accidents du travail est essentielle pour comprendre leurs causes et mettre en place des mesures de prévention efficaces. Découvrez les méthodes d\'investigation.', content: `L'analyse des accidents du travail est une étape cruciale de la démarche de prévention. Elle permet de comprendre les causes profondes d'un accident, d'identifier les défaillances du système de prévention et de mettre en place des actions correctives pour éviter la répétition.\n\n## La méthode de l'arbre des causes\n\nL'arbre des causes est la méthode la plus utilisée pour analyser les accidents du travail. Elle consiste à :\n\n1. **Recueillir les faits** : Rassembler toutes les informations objectives sur l'accident (témoignages, photographies, documents).\n2. **Identifier les événements** : Décomposer la situation en une série d'événements liés entre eux.\n3. **Construire l'arbre** : Représenter graphiquement les liens de causalité entre les événements.\n4. **Rechercher les causes profondes** : Identifier les causes organisationnelles, techniques et humaines.\n5. **Proposer des actions** : Définir des mesures correctives ciblées.\n\n## Les indicateurs clés\n\n- **Taux de fréquence (TF)** : Nombre d'accidents avec arrêt pour 1 000 000 d'heures travaillées.\n- **Taux de gravité (TG)** : Nombre de jours d'arrêt pour 1 000 heures travaillées.\n- **Indice de fréquence (IF)** : Nombre d'accidents pour 1 000 salariés.\n\n## La culture de la prévention\n\nAu-delà des analyses techniques, la prévention des accidents nécessite le développement d'une véritable culture de sécurité au sein de l'organisation, impliquant chaque niveau hiérarchique.`, categoryId: categories[2].id, coverImage: '/images/accidents.jpg', featured: false },
    { title: 'Le management intégré QSE : Vers une approche unifiée', slug: 'management-integre-qse', excerpt: 'Le management intégré QSE (Qualité, Sécurité, Environnement) permet de rationaliser les processus et d\'optimiser les ressources. Découvrez les avantages de cette approche.', content: `Le management intégré QSE (Qualité, Sécurité, Environnement) est une approche qui vise à regrouper les systèmes de management de la qualité (ISO 9001), de la santé et sécurité au travail (ISO 45001) et de l'environnement (ISO 14001) en un seul système cohérent et efficace.\n\n## Pourquoi intégrer les systèmes ?\n\nLa multiplication des systèmes de management peut entraîner une lourdeur administrative, des redondances, des conflits entre les exigences et une perte d'efficacité. L'intégration permet de :\n\n- Réduire les coûts de gestion et d'audit\n- Éviter les redondances documentaires\n- Améliorer la communication interne\n- Renforcer la cohérence des démarches\n- Faciliter la certification multi-référentiels\n\n## La structure de haut niveau (HLS)\n\nL'adoption de la structure de haut niveau (High Level Structure) par les trois normes ISO facilite grandement l'intégration. Les 10 clauses communes (contexte, leadership, planification, soutien, opérationnalité, évaluation des performances, amélioration) servent de socle commun.\n\n## Étapes de mise en place\n\nLa mise en place d'un SMQSE intégré passe par un diagnostic initial, la définition d'une politique intégrée, l'élaboration d'une cartographie des processus, la rédaction de procédures communes, la formation du personnel et la mise en place d'un système d'audit intégré.`, categoryId: categories[4].id, coverImage: '/images/integre.jpg', featured: false },
    { title: 'La formation continue en QHSE : Un investissement rentable', slug: 'formation-continue-qhse', excerpt: 'La formation continue en QHSE est un investissement stratégique pour les entreprises. Découvrez pourquoi et comment investir dans le développement des compétences QHSE.', content: `La formation continue en QHSE est un investissement stratégique qui génère un retour sur investissement mesurable. Dans un contexte réglementaire de plus en plus exigeant et un environnement professionnel en constante évolution, la montée en compétences des collaborateurs est un facteur clé de compétitivité.\n\n## Les bénéfices de la formation QHSE\n\n### Pour l'entreprise\n- Réduction des accidents du travail et des maladies professionnelles\n- Amélioration de la conformité réglementaire\n- Augmentation de la productivité et de la qualité\n- Réduction des coûts liés aux incidents\n- Amélioration de l'image de marque\n\n### Pour le salarié\n- Développement des compétences professionnelles\n- Meilleure employabilité et évolution de carrière\n- Plus grande sécurité au travail\n- Valorisation de l'expérience\n- Reconnaissance professionnelle\n\n## Les modalités de formation\n\nL'IICP propose plusieurs modalités adaptées aux besoins des professionnels et des entreprises :\n- **Formations diplômantes** : Licence et Master professionnel QHSE\n- **Formations qualifiantes** : Technicien et Technicien Supérieur QHSE\n- **Formations courtes** : Modules thématiques sur des sujets spécifiques\n- **Formations sur mesure** : Programmes adaptés aux besoins de l'entreprise\n- **VAE** : Validation des acquis de l'expérience\n\n## Le financement de la formation\n\nPlusieurs mécanismes de financement existent pour soutenir la formation QHSE : plans de développement des compétences, OPCO, compte personnel de formation (CPF), transition professionnelle et congé individuel de formation (CIF).`, categoryId: categories[5].id, coverImage: '/images/formation-continue.jpg', featured: false },
    { title: 'Les indicateurs de performance QHSE (KPI)', slug: 'indicateurs-performance-qhse-kpi', excerpt: 'Les indicateurs de performance QHSE sont essentiels pour mesurer l\'efficacité du système de management. Découvrez les KPI les plus pertinents et comment les mettre en place.', content: `Les indicateurs de performance QHSE (Key Performance Indicators) sont des outils de mesure indispensables pour piloter le système de management, suivre les progrès, identifier les dérives et communiquer sur les résultats. Un bon tableau de bord QHSE combine des indicateurs de résultat et de processus.\n\n## Indicateurs Qualité\n\n- **Taux de réclamation client** : Nombre de réclamations pour 100 produits/services\n- **Taux de non-conformité** : Pourcentage de produits/services non conformes\n- **Taux de satisfaction client** : Mesurée par enquêtes régulières\n- **Coût de la non-qualité** : Somme des coûts de prévention, d'évaluation et de défaillance\n- **Délai de traitement des réclamations** : Temps moyen entre la réception et la résolution\n\n## Indicateurs Sécurité\n\n- **Taux de fréquence des accidents (TF)** : Accidents avec arrêt / 1 000 000 heures travaillées\n- **Taux de gravité (TG)** : Jours d'arrêt / 1 000 heures travaillées\n- **Indice de fréquence (IF)** : Accidents / 1 000 salariés\n- **Taux de réalisation des actions correctives** : Pourcentage d'actions clôturées dans les délais\n\n## Indicateurs Environnement\n\n- **Consommation d'énergie** : kWh par unité produite\n- **Production de déchets** : Tonnes par période\n- **Taux de recyclage** : Pourcentage de déchets valorisés\n- **Consommation d'eau** : Mètres cubes par unité produite\n- **Émissions de CO2** : Tonnes équivalent CO2 par an\n\n## Mise en place d'un tableau de bord QHSE\n\nUn tableau de bord QHSE efficace doit être visuel, limité à un nombre raisonnable d'indicateurs (5 à 10), actualisé régulièrement, accessible à tous les niveaux hiérarchiques et aligné sur les objectifs stratégiques de l'organisation.`, categoryId: categories[4].id, coverImage: '/images/kpi.jpg', featured: false },
    { title: 'Le droit du travail et la sécurité : Ce que dit la loi', slug: 'droit-travail-securite-loi', excerpt: 'Le droit du travail impose des obligations strictes en matière de santé et sécurité au travail. Ce tour d\'horizon vous présente les principales dispositions légales à connaître.', content: `Le droit du travail français et marocain impose aux employeurs une obligation générale de sécurité envers leurs salariés. Cette obligation de résultat signifie que l'employeur doit prendre toutes les mesures nécessaires pour assurer la sécurité et protéger la santé physique et mentale des travailleurs.\n\n## Les principes généraux de prévention\n\nLe Code du travail énonce neuf principes généraux de prévention qui doivent guider toute démarche de sécurité :\n\n1. Éviter les risques\n2. Évaluer les risques qui ne peuvent pas être évités\n3. Combattre les risques à la source\n4. Adapter le travail à l'homme\n5. Tenir compte de l'état d'évolution de la technique\n6. Remplacer ce qui est dangereux par ce qui ne l'est pas\n7. Planifier la prévention\n8. Prendre des mesures de protection collective\n9. Donner les instructions appropriées aux travailleurs\n\n## Les instances représentatives\n\nLes instances représentatives du personnel (CSE, délégués du personnel) jouent un rôle crucial dans la prévention des risques professionnels. Elles ont le droit d'alerte en matière de santé et sécurité et sont consultées sur les questions liées à la sécurité au travail.\n\n## Sanctions et responsabilités\n\nLe non-respect des obligations de sécurité peut entraîner des sanctions pénales (amendes, emprisonnement), des sanctions civiles (responsabilité de l'employeur) et des sanctions administratives (mise en demeure, consignation, arrêt d'activité).`, categoryId: categories[5].id, coverImage: '/images/droit.jpg', featured: false },
  ];

